import { useRef, useState } from "react";
import { IconKeyboard } from "../../icons/generated/icons.js";
import { Button } from "../../ui/button/index.js";
import { Field } from "../../ui/field/index.js";
import { KeyboardDrawer } from "../../ui/on-screen-keyboard/index.js";
import { Surface } from "../../ui/surface/index.js";
import { Textarea } from "../../ui/textarea/index.js";
import { SectionPage, Specimen } from "../kit.js";

function DrawerDemo() {
  const frame = useRef<HTMLDivElement>(null);
  const notes = useRef<HTMLTextAreaElement>(null);
  const [open, setOpen] = useState(false);
  return (
    <Surface
      ref={frame}
      material="panel"
      radius="surface"
      className="gallery-osk-frame"
      data-size="short"
    >
      <div className="gallery-osk-frame-scroll" data-scroll-container="">
        <div className="gallery-osk-frame-form">
          <Field label="Delivery note">
            <Textarea ref={notes} minRows={3} />
          </Field>
          <div className="gallery-osk-toolbar">
            <Button
              icon={<IconKeyboard />}
              aria-pressed={open}
              onPointerDown={(event) => event.preventDefault()}
              onClick={() => {
                setOpen((previous) => !previous);
                notes.current?.focus();
              }}
            >
              Keyboard
            </Button>
          </div>
        </div>
      </div>
      <KeyboardDrawer
        open={open}
        onOpenChange={setOpen}
        target={notes}
        container={frame}
        layout="qwerty"
      />
    </Surface>
  );
}

